FACTORIES = [
    'Preshane (Metal Press)',
    'Kondanser (Condenser)',
    'Çevre Isıtıcı (Hotgas)',
    'Kalıphane (Mold Shop)',
    'Kablo Gruplama (Harness)'
]

def get_anket_analytics(grup_filtre=None, fabrika_filtre=None):
    filtered = ANKET_RECORDS
    if grup_filtre and grup_filtre != 'ALL':
        filtered = [r for r in filtered if r['grup'] == grup_filtre or r['firma'] == grup_filtre]
    if fabrika_filtre and fabrika_filtre != 'ALL':
        filtered = [r for r in filtered if r['fabrika'] == fabrika_filtre]
    
    total = len(filtered)
    if total == 0:
        filtered = ANKET_RECORDS
        total = len(filtered)
    
    genel_skor = round(sum(r['genel'] for r in filtered) / total, 1)
    
    boyutlar = []
    for d in DIMENSIONS_META:
        avg = round(sum(r[d['key']] for r in filtered) / total, 1)
        durum = 'Mükemmel' if avg >= 80 else ('İyi' if avg >= 70 else 'Gelişime Açık')
        boyutlar.append({
            'key': d['key'],
            'ad': d['ad'],
            'skor': avg,
            'ikon': d['ikon'],
            'renk': d['renk'],
            'durum': durum
        })
    
    # Fabrika kırılımları
    fab_map = {f: [] for f in FACTORIES}
    for r in filtered:
        f = r['fabrika']
        if f not in fab_map:
            fab_map[f] = []
        fab_map[f].append(r['genel'])
    
    fabrikalar = []
    fab_colors = {'Preshane': '#10b981', 'Kondanser': '#0ea5e9', 'Çevre Isıtıcı': '#6366f1', 'Kalıphane': '#f59e0b', 'Kablo': '#22609d'}
    for f in FACTORIES:
        scores = fab_map.get(f, [])
        avg = round(sum(scores)/len(scores), 1) if scores else 0.0
        c = '#22609d'
        for k, col in fab_colors.items():
            if k in f:
                c = col
                break
        fabrikalar.append({
            'ad': f,
            'skor': avg,
            'adet': len(scores),
            'renk': c
        })
    
    yuksek = sum(1 for r in filtered if r['genel'] >= 75)
    orta = sum(1 for r in filtered if 50 <= r['genel'] < 75)
    gelisime_acik = sum(1 for r in filtered if r['genel'] < 50)
    
    # NPS approximation
    promoters = sum(1 for r in filtered if r['genel'] >= 80)
    detractors = sum(1 for r in filtered if r['genel'] < 60)
    nps = round(((promoters - detractors) / total) * 100) if total else 0
    nps_str = f'+{nps}' if nps > 0 else str(nps)
    
    return {
        'toplam_yanit': total,
        'genel_skor': genel_skor,
        'nps_skoru': nps_str,
        'hedef_skor': 75.0,
        'boyutlar': boyutlar,
        'fabrikalar': fabrikalar,
        'dagilim': {
            'yuksek': yuksek,
            'orta': orta,
            'gelisime_acik': gelisime_acik
        },
        'records': filtered
    }
